function machine = makeExternalSlottedMachine()
%MAKEEXTERNALSLOTTEDMACHINE Direct canonical fixture; no legacy completion.
winding = makeResolvedWinding();
field = rnfoundry.em.rotary.radial.RadialPMField(struct( ...
    'Rbi',0.060,'Rmi',0.073,'Rmo',0.078,'Rbo',0.073, ...
    'thetam',0.40,'MagnetSkew',0.05, ...
    'MagnetMaterial',struct('Name','test magnet'), ...
    'BackIronMaterial',struct('Name','test field iron')));
armature = rnfoundry.em.rotary.radial.SlottedArmature(struct( ...
    'Position','external','Ryi',0.102,'Ryo',0.112,'Rtsb',0.082, ...
    'Rtsg',0.0805,'Ra',0.080,'tc',0.020,'tcb',0.004, ...
    'thetasg',0.035,'thetacg',0.11,'thetacy',0.13, ...
    'IronMaterial',struct('Name','test armature iron'),'Winding',winding));
machine = rnfoundry.em.rotary.radial.SlottedPMMachine(field,armature,0.1,1);
end
